"""R9/R10: evaluation helpers. Every function takes *scores first, labels second*,
so labels are consumed only after the model has produced its predictions."""

from __future__ import annotations

from typing import Dict, Iterable, List, Sequence

import numpy as np
from sklearn.metrics import average_precision_score, precision_recall_curve, roc_auc_score


def auc_roc(y_true: Sequence[int], scores: Sequence[float]) -> float:
    return float(roc_auc_score(np.asarray(y_true).astype(int), np.asarray(scores, dtype=float)))


def auc_pr(y_true: Sequence[int], scores: Sequence[float]) -> float:
    """Primary AUC-PR: sklearn average_precision_score (the ADBench convention)."""
    return float(average_precision_score(np.asarray(y_true).astype(int), np.asarray(scores, dtype=float)))


def auc_pr_trapezoid(y_true: Sequence[int], scores: Sequence[float]) -> float:
    """Secondary AUC-PR: trapezoidal area under the precision-recall curve."""
    p, r, _ = precision_recall_curve(np.asarray(y_true).astype(int), np.asarray(scores, dtype=float))
    return float(np.trapz(p, r))


def summarize(values: Iterable[float]) -> Dict[str, float]:
    v = np.asarray(list(values), dtype=float)
    return {
        "mean": float(v.mean()),
        "std": float(v.std(ddof=1)) if v.size > 1 else 0.0,
        "std_pop": float(v.std()) if v.size > 1 else 0.0,
        "min": float(v.min()),
        "max": float(v.max()),
        "n": int(v.size),
    }

