# cap the distance block at ~4M float32 entries (16 MB) so the BLAS matmul stays
# cache-friendly on any machine; chunk_rows is then derived from m
_MAX_BLOCK_ELEMS = 4_000_000


def _adaptive_chunk_rows(n: int, m: int, chunk_rows: int | None) -> int:
    if chunk_rows:
        return int(chunk_rows)
    by_block = max(256, _MAX_BLOCK_ELEMS // max(m, 1))
    return int(max(256, min(n, by_block)))

